package com.queuex.worker;
import com.fasterxml.jackson.databind.*;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Component public class WorkerListener {private final JdbcTemplate db;private final StringRedisTemplate redis;private final ObjectMapper mapper=new ObjectMapper();private final String id=System.getenv().getOrDefault("WORKER_ID", "worker-"+UUID.randomUUID());public WorkerListener(JdbcTemplate d,StringRedisTemplate r){db=d;redis=r;}
 @Scheduled(fixedDelay=10000) public void heartbeat(){redis.opsForValue().set("queuex:worker:"+id,Instant.now().toString(),Duration.ofSeconds(45));}
 @KafkaListener(topics="${app.topic:queuex.jobs}",groupId="queuex-workers") @Transactional public void consume(String message){UUID jobId;try{jobId=UUID.fromString(message);}catch(Exception e){return;}List<Map<String,Object>> rows=db.queryForList("select * from jobs where id=?",jobId);if(rows.isEmpty())return;Map<String,Object> j=rows.get(0);String status=(String)j.get("status");if(!"QUEUED".equals(status))return;int changed=db.update("update jobs set status='RUNNING', attempts=attempts+1, started_at=now(), updated_at=now() where id=? and status='QUEUED'",jobId);if(changed==0)return;int attempt=((Number)j.get("attempts")).intValue()+1;db.update("insert into job_attempts(job_id,attempt_no,worker_id,outcome) values(?,?,?,'RUNNING')",jobId,attempt,id);
 try{String type=(String)j.get("job_type");JsonNode payload=mapper.readTree((String)j.get("payload"));String result=execute(type,payload);db.update("update jobs set status='SUCCEEDED', result=?, finished_at=now(), updated_at=now(), last_error=null where id=?",result,jobId);db.update("update job_attempts set outcome='SUCCEEDED',finished_at=now() where job_id=? and attempt_no=?",jobId,attempt);}
 catch(Exception ex){int max=((Number)j.get("max_attempts")).intValue();String err=ex.getMessage()==null?"Job failed":ex.getMessage();if(attempt>=max){db.update("update jobs set status='DEAD',last_error=?,finished_at=now(),updated_at=now() where id=?",err,jobId);}else{long delay=Math.min(300,5L*(1L<<(attempt-1)));db.update("update jobs set status='QUEUED',last_error=?,scheduled_at=now() + (? * interval '1 second'),updated_at=now() where id=?",err,delay,jobId);}db.update("update job_attempts set outcome='FAILED',error=?,finished_at=now() where job_id=? and attempt_no=?",err,jobId,attempt);}}
 private String execute(String type,JsonNode p)throws Exception{return switch(type){case "echo"->p.toString();case "uppercase"->p.path("text").asText("").toUpperCase(Locale.ROOT);case "sleep"->{long ms=Math.max(0,Math.min(10000,p.path("millis").asLong(1000)));Thread.sleep(ms);yield "Slept for "+ms+" ms";}case "fail"->throw new RuntimeException("Intentional failure requested by job payload");default->throw new IllegalArgumentException("Unsupported job type: "+type);};}
}
